// @prod-safe: только просмотр. В конце selected-company-id возвращается на «test».
import { test, expect } from '../../fixtures';
import { TEST_COMPANY, expectSelected, expectUsageScreen, openUsage, restoreTest, startInTest } from './usage-helpers';

test.describe('Usage tracking: access by role (#04d347)', () => {
  test('Admin-dispatcher opens /reports/usage directly and sees the counters of company test #04d347 @desktop @prod-safe', async ({ asUser }) => {
    const dispatcher = await asUser('dispatcher');
    await startInTest(dispatcher);
    try {
      // Доступ: владелец, אדמין-מוקדן, מנהל-תפעול (комментарий программиста; принято 18.10). Сервер отдаёт данные.
      expect(await openUsage(dispatcher), 'usage_summary').toBe(200);
      await expect(dispatcher.getByText('Admin-dispatcher', { exact: true }).first()).toBeVisible();
      await expectSelected(dispatcher, TEST_COMPANY.name);
      await expect(dispatcher.getByText(/אין לך גישה|no access|access denied/i)).toHaveCount(0);

      // Те же счётчики и By person, данные компании «test» (источник: DoD «גישה למנהל/בעלים, מסוננת לעסק»).
      await expectUsageScreen(dispatcher);
    } finally {
      await restoreTest(dispatcher);
    }
  });
});
